head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30203";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30203.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.method

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_7", fn: function(){ return ((dma_listCertificate.get("reportDiv") ?? (() => { throw new Error("unresolved:" + "listCertificate.reportDiv"); })()) === '1' || (dma_listCertificate.get("reportDiv") ?? (() => { throw new Error("unresolved:" + "listCertificate.reportDiv"); })()) === '2' || (dma_listCertificate.get("reportDiv") ?? (() => { throw new Error("unresolved:" + "listCertificate.reportDiv"); })()) === '4'); } }, { id: "c_when_19", fn: function(){ return ((dma_listCertificate.get("reportDiv") ?? (() => { throw new Error("unresolved:" + "listCertificate.reportDiv"); })()) === '3'); } }, { id: "c_when_34", fn: function(){ return ((dma_listCertificate.get("reportDiv") ?? (() => { throw new Error("unresolved:" + "listCertificate.reportDiv"); })()) === '5' || (dma_listCertificate.get("reportDiv") ?? (() => { throw new Error("unresolved:" + "listCertificate.reportDiv"); })()) === '6'); } }, { id: "c_when_5", fn: function(){ return ((dma_pageContext.get("method") ?? "")==='searchListCertificate'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("certSeq")) + "]]\u003e"; } },
        { childId: "__rb1", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("comNm")) + "]]\u003e"; } },
        { childId: "__rb2", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listCmstkShrs")) + "]]\u003e"; } },
        { childId: "__rb3", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listPrefstkShrs")) + "]]\u003e"; } },
        { childId: "__rb4", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("parval")) + "]]\u003e"; } },
        { childId: "__rb5", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("cap")) + "]]\u003e"; } },
        { childId: "__rb6", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("currIsoCd")) + "]]\u003e"; } },
        { childId: "__rb7", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("ldMktTpCd")) + "]]\u003e"; } },
        { childId: "__rb8", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listDd")) + "]]\u003e"; } },
        { childId: "__rb9", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listCertUseContn")) + "]]\u003e"; } },
        { childId: "__rb10", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("today")) + "]]\u003e"; } },
        { childId: "__rb11", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("certSeq")) + "]]\u003e"; } },
        { childId: "__rb12", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("comNm")) + "]]\u003e"; } },
        { childId: "__rb13", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("ceoNm")) + "]]\u003e"; } },
        { childId: "__rb14", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("indNm")) + "]]\u003e"; } },
        { childId: "__rb15", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listCmstkShrs")) + "]]\u003e"; } },
        { childId: "__rb16", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listPrefstkShrs")) + "]]\u003e"; } },
        { childId: "__rb17", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("parval")) + "]]\u003e"; } },
        { childId: "__rb18", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("cap")) + "]]\u003e"; } },
        { childId: "__rb19", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("currIsoCd")) + "]]\u003e"; } },
        { childId: "__rb20", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("ldMktTpCd")) + "]]\u003e"; } },
        { childId: "__rb21", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listDd")) + "]]\u003e"; } },
        { childId: "__rb22", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listNo")) + "]]\u003e"; } },
        { childId: "__rb23", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listCertUseContn")) + "]]\u003e"; } },
        { childId: "__rb24", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("today")) + "]]\u003e"; } },
        { childId: "__rb25", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("comNm")) + "]]\u003e"; } },
        { childId: "__rb26", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listDd")) + "]]\u003e"; } },
        { childId: "__rb27", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("stkcertDelistDd")) + "]]\u003e"; } },
        { childId: "__rb28", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("ldMktTpCd")) + "]]\u003e"; } },
        { childId: "__rb29", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("listCertUseContn")) + "]]\u003e"; } },
        { childId: "__rb30", fn: function () { return "<![CDATA[" + String(dma_listCertificate.get("today")) + "]]\u003e"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
